<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\User;
use Spatie\Permission\Models\Role;

/**
 * Shield's Roles resource (System › Roles). Generated by `shield:generate` and trimmed to the abilities the
 * resource uses; Shield registers it (`register_role_policy`). Only the super admin manages roles in practice:
 * no seeded role holds the write permissions.
 */
final class RolePolicy
{
    public function viewAny(User $user): bool
    {
        return $user->can('ViewAny:Role');
    }

    public function view(User $user, Role $role): bool
    {
        return $user->can('View:Role');
    }

    public function create(User $user): bool
    {
        return $user->can('Create:Role');
    }

    public function update(User $user, Role $role): bool
    {
        return $user->can('Update:Role');
    }

    public function delete(User $user, Role $role): bool
    {
        return $user->can('Delete:Role');
    }

    public function deleteAny(User $user): bool
    {
        return false;
    }
}
